use v5.36;

use Carp;
use Test::More;
use Data::Dumper;
use File::Slurper qw(read_lines);

sub aref { \@_; }

sub count_letters($str) {
    my %counter;
    $counter{$_}++ 
        for (split //, $str);
    scalar keys %counter;
}

sub slide_by($by, $str) {
    my $offset = 0;
    my $count = $by;
    my $substr;
    while ($substr = substr($str, $offset++, $by)) {
        return 0 if length($substr) < $by;
        my $count_letters =  count_letters($substr) ;
        # say "$substr has $count_letters letters";
        last if count_letters($substr) >= $by;
        $count++
    }
    $count;
}

my $input = "";

say slide_by(4, "mjqjpqmgbljsphdztnvjfqwrcgsmlb");
say slide_by(14, "mjqjpqmgbljsphdztnvjfqwrcgsmlb");
say slide_by(4, $input);
say slide_by(14, $input);
